--
-- Table structure for table `grades`
--

DROP TABLE IF EXISTS `grades`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `grades` (
  `id` int NOT NULL AUTO_INCREMENT,
  `student_id` int NOT NULL,
  `class_id` int NOT NULL,
  `attendance_score` decimal(4,2) DEFAULT NULL,
  `midterm` decimal(4,2) DEFAULT NULL,
  `final` decimal(4,2) DEFAULT NULL,
  `assignment` decimal(4,2) DEFAULT NULL,
  `total` decimal(4,2) DEFAULT NULL,
  `grade_letter` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_grade` (`student_id`,`class_id`),
  KEY `idx_grades_student` (`student_id`),
  KEY `idx_grades_class` (`class_id`),
  KEY `fk_grades_updated_by` (`updated_by`),
  CONSTRAINT `fk_grades_class` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_grades_student` FOREIGN KEY (`student_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_grades_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `grades_chk_1` CHECK ((`midterm` between 0 and 10)),
  CONSTRAINT `grades_chk_2` CHECK ((`final` between 0 and 10)),
  CONSTRAINT `grades_chk_3` CHECK ((`assignment` between 0 and 10)),
  CONSTRAINT `grades_chk_4` CHECK ((`total` between 0 and 10))
) ENGINE=InnoDB AUTO_INCREMENT=30160 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

